import{_ as t,o as l,c as o,j as a,a as r}from"./chunks/framework.DdpBa4_E.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/attached/06-爱，足够吗？.md","filePath":"books/attached/06-爱，足够吗？.md","lastUpdated":1794316978000}'),n={name:"books/attached/06-爱，足够吗？.md"};function s(d,e,p,c,_,i){return l(),o("div",null,[...e[0]||(e[0]=[a("h3",{id:"爱-足够吗",tabindex:"-1"},[r("爱，足够吗？ "),a("a",{class:"header-anchor",href:"#爱-足够吗","aria-label":'Permalink to "爱，足够吗？"'},"​")],-1),a("p",null,"几年前，我们的密友塔玛拉（Tamara）开始了一段新的约会：",-1),a("p",null,"在朋友家里的一场鸡尾酒派对上，我头一次注意到了格雷格（Greg）。他真是太帅了，而我发现自己也吸引了他的眼球。几天以后，我们又和其他几个朋友一同外出就餐，我根本抗拒不了他看我的时候，眼中流露出的那种兴奋目光。而最吸引我的，莫过于他的言辞，以及他所传达出的那种想与我患难与共的暗示性许诺。那是一种关于告别孤单的许诺。他说的话诸如“塔玛拉，你不必独自在家里，你可以到我的住处来。”“只要你想，你随时随地都能打电话给我。”这些论调中，都带着一种安慰：这种安慰感，关乎你从此归属于某人，关乎你不必独自面对世界。但凡我再听得仔细一点，我便可以轻而易举地辨出一些跟这份许诺不相协调的信息，这种信息非常明确地显示出格雷格害怕过于亲密，也讨厌承诺。他多次提到，自己从不曾拥有稳定的恋情——他总是因为种种原因而厌倦自己的女朋友，并且感觉想要逃离。",-1),a("p",null,"虽然我是有能力辨别出这些问题下的暗流涌动，但那个时候，我又的确不知道如何正确地估量其中的暗示意味。唯一可以让我作为参照的，只有那种伴随我们大多数人成长起来的共识：爱可以战胜一切。于是，我就让爱征服了自己。对我来说，再没有什么事情比和他在一起更重要了。而与此同时，还有其他信息也同样预示着他在承诺方面的无能。我却对它们完全置之不理，不知哪来的自信，坚信事情到了我这里就会变得不一样。当然，事实证明我大错特错了。随着我们关系越亲密，他的信息变得愈加飘忽不定，一切都开始分崩离析；他开始跟我说，自己太忙了不能见我，当然或许每晚都不能。有时候他会声称自己整个工作周都忙疯了，向我征询是否可以只在周末见面。我虽然会默许，但内心总有一种异样的沮丧感，可是到底是哪里不对呢？",-1),a("p",null,"从那以后，我常常陷入焦虑。我总是对他的行踪全情投入，还变得极度神经过敏，特别是对那些可能预示着他想分手的事情。但是每当格雷格的行为，向我显示出充分的证据表达他的不满，他会带着恰到好处的柔情把我推开，接着又对我表示歉意，让我打消跟他分开的念头。",-1),a("p",null,"没过多久，我情绪的跌宕起伏就开始产生负效应，致使我再不能控制自己的情绪。我真的不知道该怎么做，即使自己有着不错的决断力，但还是避免跟朋友们约定计划，以免他突然约我。我已经全然对那些重要的事物丧失了兴趣。不久之后，我们的关系终于不堪重负，所有的一切都很快就戛然而止。",-1),a("p",null,"作为朋友，起先我们看到塔玛拉有了新的交往对象，而且那么热衷于此，我们都很为她高兴。但随着他们关系渐渐明朗，我们开始越来越为她对格雷格与日愈增的沉湎而担心。她的活力被焦虑与不安全感所取代。大多数时间里，她要么在痴痴等待格雷格找她，要么就对恋爱关系过于胆战心惊，以至于无法像过去一样，跟我们享受快乐时光。而她工作所受的影响也日益明晰，她曾表示过对可能失去工作的担忧。我们一直觉得塔玛拉是个多才多艺，而且十分抗压振奋的人，而后来我们开始怀疑，自己是不是误判了她的能力。即使塔玛拉能够指明，格雷格有着令人难以忍受，甚至足以跟他分手的黑历史，而且并不太值得期待，她甚至知道自己离开他或许会更快乐一些，她却仍然没办法下定决心离开。",-1),a("p",null,"作为经验丰富的心理健康专家，我们很难接受一位像塔玛拉一样精明的、受过高等教育的女性，会如此偏离与往常的形象。为什么这样一位成功的女性，会落入如此无助的地步？为什么一个在我们看来，对于生活中的挑战有着很强适应能力的人，却在这件事情上变得如此羸弱？而与她对垒的男方，也同样令人费解。为什么格雷格会发出这样含混的信息呢？明明连我们都能够看清，他是爱着她的。这些问题中蕴含着很多可能的复杂心理学解答，不过直指这种现象本质的缘由，往往简单到令人意想不到。",-1)])])}const f=t(n,[["render",s]]);export{m as __pageData,f as default};
